function syncScheduleCourseData(){schedules=L(K.schedules,[]);let changed=false;schedules.forEach(s=>{const course=courses.find(c=>String(s.courseId??'')===String(c.id)||(!s.courseId&&s.courseName&&s.courseName.includes(c.name)));if(!course)return;if(s.courseId!==course.id){s.courseId=course.id;changed=true}if(s.courseType!==course.type){s.courseType=course.type;changed=true}if(!s.store&&course.stores){s.store=course.stores;changed=true}});if(changed)S()}
