function upsertUserBookingMirror(schedule,member){if(!member.isCurrentUser)return;const booking={id:member.bookingId,productId:member.productId||`product-${schedule.courseId}`,courseId:schedule.courseId,courseName:normalizeUserCourseName({name:schedule.courseName.replace(/小班$/,''),type:schedule.courseType}),coachName:coachName(),store:schedule.store,scheduleId:schedule.id,date:schedule.date,start:schedule.start,end:schedule.end,type:schedule.courseType,status:member.status,source:member.source||'user',customerName:member.name,customerPhone:member.phone,createdAt:member.createdAt||new Date().toISOString(),cancelRequestedAt:member.cancelRequestedAt||'',completeConfirmExpireAt:member.completeConfirmExpireAt||'',completedAt:member.completedAt||'',isCurrentUser:true};const idx=userBookings.findIndex(item=>String(item.id)===String(member.bookingId));if(idx>-1)userBookings[idx]={...userBookings[idx],...booking};else userBookings.unshift(booking)}
