function ensureScheduleMembers(schedule){let changed=false;if(!Array.isArray(schedule.members)){schedule.members=[];changed=true}schedule.members=schedule.members.map((member,index)=>{if(member.bookingId&&member.status&&member.source)return member;changed=true;return{bookingId:member.bookingId||`${schedule.id}-member-${index+1}`,name:member.name||'学员',phone:member.phone||'',time:member.time||'教练端预约',status:member.status||(member.confirmStatus==='已预约'?'待上课':'待上课'),source:member.source||(isCurrentUserProfile(member.name,member.phone)?'user':'coach'),isCurrentUser:member.isCurrentUser??isCurrentUserProfile(member.name,member.phone),createdAt:member.createdAt||new Date().toISOString(),cancelRequestedAt:member.cancelRequestedAt||'',completeConfirmExpireAt:member.completeConfirmExpireAt||'',completedAt:member.completedAt||''}});schedule.members.forEach(member=>upsertUserBookingMirror(schedule,member));syncScheduleBookedCount(schedule);if(changed)S();return schedule.members}
function settleBookingTimeouts(){let changed=false;schedules.forEach(schedule=>{ensureScheduleMembers(schedule);schedule.members=schedule.members.map(member=>{if(member.status==='待学员确认完课'&&member.completeConfirmExpireAt&&new Date(member.completeConfirmExpireAt).getTime()<=Date.now()){changed=true;const next={...member,status:'已完课',completedAt:member.completeConfirmExpireAt||new Date().toISOString()};upsertUserBookingMirror(schedule,next);return next}return member});if(changed)syncScheduleBookedCount(schedule)});if(changed)S()}
