window.clearUserContractCanvas=function(){const canvas=$('userContractCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);userContractDrawing=false;userContractHasStroke=false}
function setupUserContractCanvas(){const canvas=$('userContractCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#ffffff';ctx.lineWidth=2.2;userContractDrawing=false;userContractHasStroke=false;const pointFromEvent=e=>{const rect=canvas.getBoundingClientRect();const clientX=e.touches?e.touches[0].clientX:e.clientX;const clientY=e.touches?e.touches[0].clientY:e.clientY;return{x:(clientX-rect.left)*(canvas.width/rect.width),y:(clientY-rect.top)*(canvas.height/rect.height)}};const start=e=>{const p=pointFromEvent(e);ctx.beginPath();ctx.moveTo(p.x,p.y);userContractDrawing=true;userContractHasStroke=true;e.preventDefault()};const move=e=>{if(!userContractDrawing)return;const p=pointFromEvent(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()};const end=()=>{userContractDrawing=false};canvas.onmousedown=start;canvas.onmousemove=move;canvas.onmouseup=end;canvas.onmouseleave=end;canvas.ontouchstart=start;canvas.ontouchmove=move;canvas.ontouchend=end}
function renderUserContractPage(){const product=getUserProduct(currentContractProductId||currentUserProductId);const record=product?getUserContractRecord(product.id):null;const signed=!!record;const btn=$('userContractBtn');if(!product){$('userContractBox').innerHTML='<div class="user-empty">未找到合同对应课程</div>';btn.innerText='返回';return}const signedBlock=signed?(record.signatureData?`<label>手写签名</label><div class="user-sign-preview"><img src="${record.signatureData}" alt="手写签名" /></div>`:`<label>手写签名</label><input class="user-contract-input" value="${record.signer||'已签署'}" disabled />`):`<label for="userContractCanvas">手写签名</label><canvas id="userContractCanvas" class="user-sign-board" width="640" height="260"></canvas><div class="user-sign-actions"><button class="mini-btn ghost" onclick="clearUserContractCanvas()">重签</button></div><label class="user-contract-check"><input id="userContractAgree" type="checkbox" />我已阅读并同意上述课程预约电子合同内容</label>`;$('userContractBox').innerHTML=`<div class="user-contract-badge">${signed?'已签约':'预约前需签约'}</div><div class="user-contract-title">${product.name}电子合同</div><div class="user-contract-meta">${product.coachName} · ${product.store}${signed?`<br/>签署时间：${fmtContractTime(record.signedAt)}`:''}</div><div class="user-contract-card"><strong>课程约定</strong><div>甲方购买并预约 ${product.name} 课程后，需按预约时间到店上课。</div><div>乙方将依据预约记录为甲方提供对应训练服务。</div><div>每次成功预约将按规则核销 1 节对应课时。</div></div><div class="user-contract-list">1. 学员需遵守预约与取消规则，并保证签署信息真实有效。<br/>2. 门店将基于已签署合同和预约记录提供训练服务。<br/>3. 课程开始前未按规则取消的，按当前业务规则处理。<br/>4. 完成签署后，可继续进行当前课程预约。</div><div class="user-contract-sign">${signedBlock}</div><div class="user-contract-foot">${signed?'当前课程已完成签约，可直接预约。':'签署完成后，当前课程后续预约将直接跳过本页面。'}</div>`;btn.innerText=signed?(pendingBookingAfterContract?'继续预约':'关闭'):'完成签署并继续预约';if(!signed)setupUserContractCanvas()}
