window.startPurchase=function(productId){const course=courses.find(c=>c.id===productId);if(!course)return;const addRemain=Math.max(1,Number(course.hours)||1);const product={id:`product-${Date.now()}`,courseId:course.id,name:normalizeUserCourseName(course),type:course.type,remain:addRemain,coachName:coachName(),store:course.stores||coachStoreName()};userProducts.push(product);S();purchaseProductId=product.id;purchaseCourseType=product.type==='一对多'?'group':'private';saveUserState();showPage('userOrderConfirmPage')}
