window.goHeroSlide=function(i){const t=$('uhHeroTrack');if(!t)return;t.style.transform=`translateX(-${i*100}%)`;t.dataset.index=i;const ds=document.querySelectorAll('#uhHeroDots .uh-hero-dot');ds.forEach((d,j)=>{d.classList.toggle('active',j===i)});if(window._heroTimer){clearInterval(window._heroTimer);const photos=coachProfile&&coachProfile.photos&&coachProfile.photos.length?coachProfile.photos:[coachAvatar()];if(photos.length>1){window._heroTimer=setInterval(()=>{const tr=$('uhHeroTrack');if(!tr)return;let idx=parseInt(tr.dataset.index||'0',10);idx=(idx+1)%photos.length;tr.style.transform=`translateX(-${idx*100}%)`;tr.dataset.index=idx;const dts=document.querySelectorAll('#uhHeroDots .uh-hero-dot');dts.forEach((d,j)=>{d.classList.toggle('active',j===idx)})},3500)}}}
