window.openUserBookingConfirm=function(){const product=getUserProduct(purchaseProductId||currentUserProductId);const isGroup=product&&product.type==='一对多';if(isGroup){$('userConfirmText').innerHTML=`将预约 <strong>${product.name}</strong>，成功预约将使用1节小班课时。`;$('userConfirmMask').style.display='block';return}const slot=getUserSlot(selectedTimelineScheduleId);if(!canUserBookSlot(slot,product)){toast(Number(product?.remain||0)>0?'请选择可预约时段':'剩余课时不足');return}$('userConfirmText').innerHTML=`将预约 ${fmtUserDateTime(slot.date,slot.start,slot.end)} 的训练，成功预约将使用1节${product.type==='一对多'?'小班':'私教'}课时。`;$('userConfirmMask').style.display='block'}
