window.confirmTimelineBooking=function(){const product=getUserProduct(purchaseProductId||currentUserProductId);const isGroup=product&&product.type==='一对多';if(isGroup){if(Number(product.remain||0)<=0){hideTimelineConfirm();toast('剩余课时不足');return}schedules=L(K.schedules,[]);const nextSchedule=getUserCourseSchedules(product).find(s=>{if(s.status==='停止预约'||s.status==='已取消')return false;if(getUserRemainingSeats(s)<=0)return false;return !hasCurrentUserBookedSlot(s.id)});if(!nextSchedule){hideTimelineConfirm();toast('暂无可预约时段');return}product.remain=Math.max(0,Number(product.remain||0)-1);ensureScheduleMembers(nextSchedule);const member={bookingId:makeBookingId(),name:'小明',phone:'188****0000',time:'用户端预约',status:'待上课',source:'user',isCurrentUser:true,productId:product.id,createdAt:new Date().toISOString(),cancelRequestedAt:'',completeConfirmExpireAt:'',completedAt:''};nextSchedule.members.push(member);upsertUserBookingMirror(nextSchedule,member);syncScheduleBookedCount(nextSchedule);newBookingId=member.bookingId;S();hideTimelineConfirm();showPage('userSuccessPage');return}schedules=L(K.schedules,[]);const slot=getUserSlot(selectedTimelineScheduleId);if(!canUserBookSlot(slot,product)){hideTimelineConfirm();renderUserBookingPage();toast('当前时段已不可预约');return}ensureScheduleMembers(slot);if(userBookings.some(booking=>String(booking.scheduleId)===String(slot.id)&&booking.status!=='已取消')){hideTimelineConfirm();toast('这个时段已经预约过了');return}product.remain=Math.max(0,Number(product.remain||0)-1);const booking={bookingId:makeBookingId(),name:'小明',phone:'188****0000',time:'用户端预约',status:'待上课',source:'user',isCurrentUser:true,productId:product.id,createdAt:new Date().toISOString(),cancelRequestedAt:'',completeConfirmExpireAt:'',completedAt:''};slot.members.push(booking);upsertUserBookingMirror(slot,booking);syncScheduleBookedCount(slot);newBookingId=booking.bookingId;S();hideTimelineConfirm();showPage('userSuccessPage')}
function userBookingNote(booking){if(booking.status==='待上课'&&hoursUntilBooking(booking)<3)return'距开课不足 3 小时，需联系教练协商取消。';if(booking.status==='待教练处理取消')return'取消申请已提交，等待教练处理。';if(booking.status==='待学员确认完课')return'请在 24 小时内确认完课，超时系统会自动完课。';if(booking.status==='未到场')return'教练未同意取消，本次课程按未到场处理并正常核销。';if(booking.status==='已完课')return'';return''}
function userBookingActions(booking){if(booking.status==='待上课')return`<button class="mini-btn${hoursUntilBooking(booking)>=3?'':' secondary'}" onclick="handleUserCancel('${booking.id}')">${hoursUntilBooking(booking)>=3?'取消预约':'联系教练取消'}</button>`;if(booking.status==='待学员确认完课')return`<button class="mini-btn" onclick="confirmUserFinish('${booking.id}')">确认完课</button>`;return''}
window.handleUserCancel=function(bookingId){settleBookingTimeouts();const booking=userBookings.find(item=>String(item.id)===String(bookingId));if(!booking)return;if(hoursUntilBooking(booking)>=3){cancelBookingSeat(bookingId);toast('已取消预约')}else{updateBookingRecord(bookingId,{status:'待教练处理取消',cancelRequestedAt:new Date().toISOString()});toast('已提交取消申请，请联系教练处理')}renderUserBookings();if(currentScheduleId)openDetail(currentScheduleId)}
window.confirmUserFinish=function(bookingId){updateBookingRecord(bookingId,{status:'已完课',completedAt:new Date().toISOString()});toast('已确认完课');renderUserBookings();if(currentScheduleId)openDetail(currentScheduleId)}
function renderUserSuccessPage(){const booking=userBookings.find(item=>String(item.id)===String(newBookingId))||userBookings[userBookings.length-1];const product=booking?getUserProduct(booking.productId):null;const isGroup=booking&&booking.type==='一对多';$('usInfoCard').innerHTML=booking?`<div class="us-info-row"><span class="us-info-icon">&#9679;</span><span class="us-info-label">教练：</span><span class="us-info-value">${booking.coachName}</span></div><div class="us-info-row"><span class="us-info-icon">&#9679;</span><span class="us-info-label">门店：</span><span class="us-info-value">${booking.store}</span></div><div class="us-info-row"><span class="us-info-icon">&#9679;</span><span class="us-info-label">时段：</span><span class="us-info-value">${fmtUserDateTime(booking.date,booking.start,booking.end)}</span></div>`:'<div class="us-info-row"><span class="us-info-value">暂无预约信息</span></div>';$('usRules').innerHTML=isGroup?`<strong>小班预约训练与取消规则：</strong>1、预约成功后将使用1节小班课时，每次训练时间由教练统一安排；<br/>2、如需取消预约，请提前一天操作，训练当日无法取消预约。`:`<strong>私教预约训练与取消规则：</strong>1、预约成功后将使用1节私教课时，每次训练1个小时；<br/>2、每日21:00更新后续预约时间，每周六21:00更新下周可预约时间；<br/>3、同一课程单日最多可预约2次训练，请合理安排您的时间；<br/>4、如需取消预约，请提前一天操作，训练当日无法取消预约。`}
