function renderUserBookings(){userBookings=L(K.userBookings,[]);settleBookingTimeouts();const list=userBookings;const box=$('userBookingsList');if(!list.length){box.innerHTML='<div class="user-empty"><div class="empty-title">暂无预约记录</div><div>完成预约后，会在这里展示你的课程安排。</div></div>';return}box.innerHTML=list.map(booking=>{const wayText=booking.source==='user'?'学员预约':'教练代约';const timeText=booking.createdAt?new Date(booking.createdAt).toLocaleString('zh-CN',{hour12:false}):'--';const doneText=booking.status==='已完课'&&booking.completedAt?new Date(booking.completedAt).toLocaleString('zh-CN',{hour12:false}):'';return`<div class="user-booking-card"><div class="user-booking-head"><div><div class="user-booking-name">${booking.courseName}</div><div class="user-store">${booking.coachName} · ${booking.store}</div></div><div class="user-status">${booking.status}</div></div><div class="user-booking-time">${fmtUserDateTime(booking.date,booking.start,booking.end)}</div><div class="user-booking-meta"><div>预约方式：${wayText}</div><div>预约时间：${timeText}</div>${doneText?`<div>完课时间：${doneText}</div>`:''}</div>${userBookingActions(booking)?`<div class="user-booking-actions">${userBookingActions(booking)}</div>`:''}${userBookingNote(booking)?`<div class="user-booking-note">${userBookingNote(booking)}</div>`:''}</div>`}).join('')}
